-- Lab-confirmed counts per site and pathogen. Synthetic (docs/design/master/sample_data.json). Not real people or real surveillance.
SELECT
  CAST(NULLIF(c[1], '') AS INTEGER) AS site_key,
  NULLIF(c[2], '') AS pathogen,
  CAST(NULLIF(c[3], '') AS INTEGER) AS confirmed
FROM (SELECT string_to_array(rec, chr(31)) AS c FROM unnest(string_to_array('0Malaria30Respiratory00Diarrheal00Measles01Malaria01Respiratory01Diarrheal31Measles02Malaria02Respiratory32Diarrheal02Measles03Malaria03Respiratory03Diarrheal03Measles14Malaria24Respiratory04Diarrheal04Measles05Malaria15Respiratory05Diarrheal05Measles06Malaria26Respiratory06Diarrheal06Measles07Malaria17Respiratory07Diarrheal07Measles08Malaria08Respiratory08Diarrheal08Measles09Malaria09Respiratory09Diarrheal09Measles010Malaria010Respiratory010Diarrheal010Measles011Malaria011Respiratory011Diarrheal011Measles012Malaria012Respiratory012Diarrheal012Measles013Malaria013Respiratory013Diarrheal013Measles014Malaria014Respiratory014Diarrheal014Measles015Malaria015Respiratory015Diarrheal015Measles016Malaria016Respiratory016Diarrheal016Measles017Malaria017Respiratory017Diarrheal017Measles018Malaria018Respiratory018Diarrheal018Measles019Malaria019Respiratory019Diarrheal019Measles020Malaria020Respiratory220Diarrheal020Measles021Malaria021Respiratory021Diarrheal021Measles022Malaria022Respiratory022Diarrheal022Measles023Malaria023Respiratory023Diarrheal023Measles0', chr(30))) AS t(rec)) AS packed